def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Normalize the starting point
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components and filter out empty strings
    components = [c for c in path.split('/') if c]

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        if comp == '.':
            # Skip current directory reference
            i += 1
            continue
        elif comp == '..':
            # Move to parent
            if current == '':
                current = ''
            else:
                current = '/'.join(current.split('/')[:-1])
            i += 1
            continue
        else:
            # Regular name component
            if current == '':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            # Check if this path is a symlink
            if new_path in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[new_path]

                # Process the target
                if target.startswith('/'):
                    current = ''
                    target_components = [c for c in target.split('/') if c]
                else:
                    # Relative target: resolve relative to the directory containing the link
                    if current == '':
                        current = ''
                    else:
                        current = '/'.join(current.split('/')[:-1])
                    target_components = [c for c in target.split('/') if c]

                # Insert target components at current position
                components = components[:i] + target_components + components[i+1:]
                # Don't increment i, process from the beginning of the inserted components
                continue
            else:
                current = new_path
                i += 1

    # Return the result
    if current == '':
        return '/'
    else:
        return current

